"""Schemas for Vectora AI Local Assistant integration."""
from __future__ import annotations

from typing import Any, Dict, List, Optional
from pydantic import BaseModel, Field


class AssistantHealthResponse(BaseModel):
    status: str
    ollama_base_url: str
    target_model: str
    model_loaded: bool
    available_models: List[str] = Field(default_factory=list)
    guardrail: str = (
        "LLM advisory service only. Official metrics and production decisions "
        "must be generated by validated scripts, not LLM inference."
    )


class AssistantQueryRequest(BaseModel):
    prompt: str
    system_prompt: Optional[str] = None
    temperature: float = Field(default=0.2, ge=0.0, le=1.0)
    json_mode: bool = False


class ReportReviewRequest(BaseModel):
    report_title: str
    report_content: str
    focus_areas: Optional[List[str]] = Field(
        default_factory=lambda: ["ASD-STE100 compliance", "Scientific claims", "Statistical consistency"]
    )


class TrainingLogInterpretationRequest(BaseModel):
    log_content: str
    architecture: Optional[str] = "EfficientNet-B0"
    num_folds: Optional[int] = 4


class AuditScriptReviewRequest(BaseModel):
    script_name: str
    script_content: str
    hardware_target: Optional[str] = "Intel Core i7-2600 (Sandy Bridge, AVX, 16GB RAM)"


class ExperimentConfigReviewRequest(BaseModel):
    experiment_name: str
    config_details: Dict[str, Any]


class ExplainResultRequest(BaseModel):
    genus: str
    raw_scores: Optional[Dict[str, float]] = None
    scan_id: Optional[str] = None
    quality_feedback: Optional[Dict[str, Any]] = None


class SummarizeHistoryRequest(BaseModel):
    submissions: List[Dict[str, Any]]


class AssistantResponse(BaseModel):
    success: bool
    model: str
    duration_ms: float
    response: str
    structured_json: Optional[Dict[str, Any]] = None
    guardrail_notice: str = (
        "DISCLAIMER: LLM advisory output. Prohibited from computing official evaluation metrics, "
        "modifying model artifacts, or altering dataset partitions."
    )
